ClockDialEngraverMaker.productStock = {}; ClockDialEngraverMaker.buildings = {}; ClockDialEngraverMaker.maker = nil; ClockDialEngraverMaker.activeMaking = {}; ClockDialEngraverMaker.totalProducts = 0; ClockDialEngraverMaker.dayTimer = 0
function ClockDialEngraverMaker.init() ClockDialEngraverMaker.ironStock=14; ClockDialEngraverMaker.bronzeStock=12; ClockDialEngraverMaker.woodStock=14; ClockDialEngraverMaker.leatherStock=8; ClockDialEngraverMaker.silverStock=10; ClockDialEngraverMaker.goldStock=6; ClockDialEngraverMaker.jewelStock=4; ClockDialEngraverMaker.pearlStock=4; ClockDialEngraverMaker.productStock={}; ClockDialEngraverMaker.buildings={}; ClockDialEngraverMaker.maker=nil; ClockDialEngraverMaker.activeMaking={}; ClockDialEngraverMaker.totalProducts=0; ClockDialEngraverMaker.dayTimer=0; print("[ClockDialEngraverMaker] Royal Clock Dial Engraver Maker System initialized (6 products, 4 buildings)") end
function ClockDialEngraverMaker.hireMaker(n,s) s=s or math.random(55,90); local c=595+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ClockDialEngraverMaker.maker={name=n or ("Rezkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Rezkar najet: %s (spretnost: %d)",ClockDialEngraverMaker.maker.name,s),"success") end; return true end
function ClockDialEngraverMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ClockDialEngraverMaker.build(id) local ok,e=ClockDialEngraverMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ClockDialEngraverMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ClockDialEngraverMaker.getQualityBonus() local b=0; for _,bd in ipairs(ClockDialEngraverMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ClockDialEngraverMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ClockDialEngraverMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and ClockDialEngraverMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and ClockDialEngraverMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and ClockDialEngraverMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ClockDialEngraverMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ClockDialEngraverMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ClockDialEngraverMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ClockDialEngraverMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ClockDialEngraverMaker.buildings==0 then return false,"Potrebna rezkalna delavnica" end; if not ClockDialEngraverMaker.maker then return false,"Potreben rezkar" end; return true end
function ClockDialEngraverMaker.make(pt,qty) qty=qty or 1; local ok,e=ClockDialEngraverMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ClockDialEngraverMaker.ironStock=ClockDialEngraverMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then ClockDialEngraverMaker.bronzeStock=ClockDialEngraverMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then ClockDialEngraverMaker.woodStock=ClockDialEngraverMaker.woodStock-d.woodCost*qty end; if d.leatherCost then ClockDialEngraverMaker.leatherStock=ClockDialEngraverMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ClockDialEngraverMaker.silverStock=ClockDialEngraverMaker.silverStock-d.silverCost*qty end; if d.goldCost then ClockDialEngraverMaker.goldStock=ClockDialEngraverMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ClockDialEngraverMaker.jewelStock=ClockDialEngraverMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ClockDialEngraverMaker.pearlStock=ClockDialEngraverMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ClockDialEngraverMaker.maker then t=math.max(1,t-math.floor(ClockDialEngraverMaker.maker.skill/13)) end; table.insert(ClockDialEngraverMaker.activeMaking,{id="clockdialengraver_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ClockDialEngraverMaker.completeMaking(m) local q=1.0+(ClockDialEngraverMaker.getQualityBonus()/100); if ClockDialEngraverMaker.maker then q=q+(ClockDialEngraverMaker.maker.skill/140) end; q=math.min(2.5,q); ClockDialEngraverMaker.productStock[m.productType]=(ClockDialEngraverMaker.productStock[m.productType] or 0)+m.quantity; ClockDialEngraverMaker.totalProducts=ClockDialEngraverMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ClockDialEngraverMaker.maker then ClockDialEngraverMaker.maker.itemsMade=ClockDialEngraverMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ClockDialEngraverMaker.maker.skill=math.min(100,ClockDialEngraverMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Rezkar izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"clockdialengraver.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function ClockDialEngraverMaker.update(dt) if not _G.state then return end; ClockDialEngraverMaker.dayTimer=ClockDialEngraverMaker.dayTimer+dt; if ClockDialEngraverMaker.dayTimer>=30 then ClockDialEngraverMaker.dayTimer=0; for i=#ClockDialEngraverMaker.activeMaking,1,-1 do local m=ClockDialEngraverMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ClockDialEngraverMaker.completeMaking(m); table.remove(ClockDialEngraverMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ClockDialEngraverMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ClockDialEngraverMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ClockDialEngraverMaker.getStats() return {ironStock=ClockDialEngraverMaker.ironStock,bronzeStock=ClockDialEngraverMaker.bronzeStock,woodStock=ClockDialEngraverMaker.woodStock,leatherStock=ClockDialEngraverMaker.leatherStock,silverStock=ClockDialEngraverMaker.silverStock,goldStock=ClockDialEngraverMaker.goldStock,jewelStock=ClockDialEngraverMaker.jewelStock,pearlStock=ClockDialEngraverMaker.pearlStock,productStock=ClockDialEngraverMaker.productStock,numBuildings=#ClockDialEngraverMaker.buildings,hasMaker=ClockDialEngraverMaker.maker~=nil,makerName=ClockDialEngraverMaker.maker and ClockDialEngraverMaker.maker.name or "—",makerSkill=ClockDialEngraverMaker.maker and ClockDialEngraverMaker.maker.skill or 0,activeMaking=#ClockDialEngraverMaker.activeMaking,totalProducts=ClockDialEngraverMaker.totalProducts} end
